54	              onBlur={handleBlur}
55	              error={touched.permitType && Boolean(errors.permitType)}
56	              helperText={touched.permitType && errors.permitType}
57	              fullWidth
58	            />
59	
60	            <TextField
61	              label="Title"
62	              name="title"
63	              value={values.title}
64	              onChange={handleChange}
65	              onBlur={handleBlur}
66	              error={touched.title && Boolean(errors.title)}
67	              helperText={touched.title && errors.title}
68	              fullWidth
69	            />
70	
71	            <TextField
72	              select
73	              label="Country"
74	              name="countryCode"
75	              value={values.countryCode}
76	              onChange={(e) => {
77	                const code = e.target.value;
78	                setFieldValue('countryCode', code);
79	                const country = COUNTRIES.find((c) => c.code === code);
80	                if (country && !values.currencyCode) {
81	                  setFieldValue('currencyCode', country.currency);
82	                }
83	              }}
84	              onBlur={handleBlur}
85	              error={touched.countryCode && Boolean(errors.countryCode)}
86	              helperText={touched.countryCode && errors.countryCode}
87	              fullWidth
88	            >
89	              {COUNTRIES.map((c) => (
90	                <MenuItem key={c.code} value={c.code}>
91	                  {c.name}
92	                </MenuItem>
93	              ))}
94	            </TextField>
95	          </FormSection>
96	
97	          <FormSection title="Permit Details" description="Describe the permit and who is eligible to apply.">
98	            <TextField
99	              label="Description"
100	              name="description"
101	              value={values.description}
102	              onChange={handleChange}
103	              onBlur={handleBlur}
104	              error={touched.description && Boolean(errors.description)}
105	              helperText={touched.description && errors.description}
106	              multiline
107	              minRows={3}
108	              fullWidth
109	              sx={{ gridColumn: { sm: '1 / span 2' } }}
110	            />
111	
112	            <TextField
113	              label="Eligibility Criteria"
114	              name="eligibilityCriteria"
115	              value={values.eligibilityCriteria}
116	              onChange={handleChange}
117	              onBlur={handleBlur}
118	              error={touched.eligibilityCriteria && Boolean(errors.eligibilityCriteria)}
119	              helperText={touched.eligibilityCriteria && errors.eligibilityCriteria}
120	              multiline
121	              minRows={3}
122	              fullWidth
123	              sx={{ gridColumn: { sm: '1 / span 2' } }}
124	            />
