import { Chip } from '@mui/material';
import { PERMIT_STATUS_LABELS } from '../../utils/enums';

// Shared chip rendering content/review status (Section 12)
const COLOR_MAP = {
  DRAFT: 'default',
  PUBLISHED: 'success',
  ARCHIVED: 'default',
  PENDING: 'warning',
  IN_REVIEW: 'info',
  APPROVED: 'success',
  CHANGES_REQUESTED: 'warning',
  REJECTED: 'error',
};

export default function StatusChip({ status }) {
  if (!status) return null;
  return (
    <Chip
      size="small"
      label={PERMIT_STATUS_LABELS[status] || status}
      color={COLOR_MAP[status] || 'default'}
      variant={status === 'ARCHIVED' ? 'outlined' : 'filled'}
    />
  );
}

require('dotenv').config();

module.exports = {
  port: process.env.PORT || 5000,
  // `true` reflects the request's Origin header (permissive, no-auth local
  // dev default); set CLIENT_ORIGIN to a specific origin to lock it down.
  clientOrigin: process.env.CLIENT_ORIGIN || true,
  // Optional override for where the SQLite file lives; defaults to
  // server/database/hrckmp.db (see config/sqliteDb.js).
  sqliteDbPath: process.env.SQLITE_DB_PATH || null,
};

// TODO: create and export the team's shared database connection using
// config/env.js (per the HLD, this is expected to be a MySQL/mysql2 pool).
//
// Reserved placeholder — not yet implemented. No feature is connected to
// this file. The Work Permit feature (Developer 2) uses its own SQLite
// connection at config/sqliteDb.js in the meantime; it does not use this
// file.
module.exports = null;

