const { chromium } = require('playwright');

const SCREENSHOT_DIR = __dirname;
let screenshotCount = 0;

async function screenshot(page, name) {
  screenshotCount += 1;
  const path = `${SCREENSHOT_DIR}/${String(screenshotCount).padStart(2, '0')}-${name}.png`;
  await page.screenshot({ path, fullPage: true });
  console.log(`Saved screenshot: ${path}`);
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const consoleErrors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('pageerror', (err) => consoleErrors.push(`pageerror: ${err.message}`));

  try {
    console.log('--- Navigate to app root ---');
    await page.goto('http://localhost:5173/', { waitUntil: 'networkidle' });
    await page.click('text=Review & Approval');
    await page.waitForSelector('text=Review & Approval Workflow');
    await page.waitForSelector('text=Review: Singapore Employment Pass copy');
    await screenshot(page, 'list-initial');

    console.log('--- Check seeded rows count ---');
    const rowCount = await page.locator('table tbody tr').count();
    console.log(`Table rows visible: ${rowCount}`);

    console.log('--- Search filter ---');
    await page.fill('input[placeholder="Search by title"]', 'Malaysia');
    await page.waitForTimeout(300);
    const filteredRows = await page.locator('table tbody tr').count();
    console.log(`Rows after searching "Malaysia": ${filteredRows}`);
    await screenshot(page, 'list-search-filtered');
    await page.fill('input[placeholder="Search by title"]', '');

    console.log('--- Status filter ---');
    await page.click('label:has-text("Status") + div, div:has-text("All Statuses")');
    // Use the MUI select by role instead for reliability
    await page.locator('div[role="combobox"]', { hasText: 'All Statuses' }).click();
    await page.getByRole('option', { name: 'Approved' }).click();
    await page.waitForTimeout(300);
    const approvedRows = await page.locator('table tbody tr').count();
    console.log(`Rows after filtering status=Approved: ${approvedRows}`);
    await screenshot(page, 'list-status-filtered');
    // Clear filters
    await page.click('text=Clear Filters');
    await page.waitForTimeout(300);

    console.log('--- Create new review request ---');
    await page.click('text=New Review Request');
    await page.waitForSelector('text=New Review Request');
    await page.fill('input[name="title"]', 'Browser Test Review');
    await page.locator('div[role="combobox"]', { hasText: 'Work Permit' }).first().click();
    await page.getByRole('option', { name: 'Work Permit', exact: true }).click();
    await page.fill('input[name="targetId"]', '2');
    await screenshot(page, 'form-filled');
    await page.click('button:has-text("Create Review Request")');

    await page.waitForSelector('text=Browser Test Review');
    console.log('--- Detail page after create ---');
    await screenshot(page, 'detail-after-create');
    const detailUrl = page.url();
    console.log(`Detail URL: ${detailUrl}`);

    console.log('--- Edit: change status to In Review ---');
    await page.click('button:has-text("Edit")');
    await page.waitForSelector('text=Edit Review Request');
    await page.locator('div[role="combobox"]', { hasText: 'Pending' }).click();
    await page.getByRole('option', { name: 'In Review' }).click();
    await screenshot(page, 'form-edit-status');
    await page.click('button:has-text("Save Changes")');

    await page.waitForSelector('text=Browser Test Review');
    await page.waitForSelector('text=In Review');
    console.log('--- Detail page after edit ---');
    await screenshot(page, 'detail-after-edit');

    console.log('--- Archive ---');
    await page.click('button:has-text("Archive")');
    await page.waitForSelector('text=Archive review request?');
    await screenshot(page, 'archive-confirm-dialog');
    await page.click('button:has-text("Archive Request")');

    await page.waitForSelector('text=Archived');
    console.log('--- Detail page after archive ---');
    await screenshot(page, 'detail-after-archive');

    const archiveBtn = page.locator('button:has-text("Archive")');
    const isDisabled = await archiveBtn.isDisabled();
    console.log(`Archive button disabled after archiving: ${isDisabled}`);

    console.log('--- Console errors collected ---');
    console.log(consoleErrors.length ? consoleErrors.join('\n') : '(none)');
  } catch (err) {
    console.error('TEST FAILED:', err);
    await screenshot(page, 'FAILURE');
    process.exitCode = 1;
  } finally {
    await browser.close();
  }
})();

