  const page = await browser.newPage();

  page.on('console', (msg) => console.log(`[console.${msg.type()}]`, msg.text()));
  page.on('pageerror', (err) => console.log('[pageerror]', err.message));
  page.on('requestfailed', (req) =>
    console.log('[requestfailed]', req.method(), req.url(), req.failure()?.errorText)
  );
  page.on('response', async (res) => {
    if (res.url().includes('/api/v1/reviews')) {
      console.log('[response]', res.request().method(), res.url(), res.status());
    }
  });

  await page.goto('http://localhost:5173/reviews/new', { waitUntil: 'networkidle' });
  await page.waitForSelector('text=New Review Request');

  console.log('--- filling title ---');
  await page.getByLabel('Title').fill('Repro Bug Review');

  console.log('--- opening Target Type dropdown ---');
  await page.getByLabel('Target Type').click();
  await page.screenshot({ path: `${__dirname}/repro-01-dropdown-open.png` });
  await page.getByRole('option', { name: 'Work Permit', exact: true }).click();

  console.log('--- filling target id ---');
  await page.getByLabel('Target ID').fill('2');

  await page.screenshot({ path: `${__dirname}/repro-02-form-filled.png` });

  console.log('--- clicking Create Review Request ---');
  await page.getByRole('button', { name: 'Create Review Request' }).click();

  await page.waitForTimeout(3000);
  await page.screenshot({ path: `${__dirname}/repro-03-after-submit.png` });
  console.log('Current URL:', page.url());

  const btn = page.getByRole('button', { name: 'Create Review Request' });
  if (await btn.count()) {
    console.log('Submit button still present, disabled:', await btn.isDisabled());
  } else {
    console.log('Submit button no longer present (navigated away)');
  }

  await browser.close();
})();

