(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('console', (msg) => msg.type() === 'error' && console.log('[console.error]', msg.text()));
  page.on('requestfailed', (req) =>
    console.log('[requestfailed]', req.method(), req.url(), req.failure()?.errorText)
  );

  // Simulate a backend hiccup / network failure on the create request only.
  await page.route('**/api/v1/reviews', (route) => {
    if (route.request().method() === 'POST') {
      return route.abort('connectionrefused');
    }
    return route.continue();
  });

  await page.goto('http://localhost:5173/reviews/new', { waitUntil: 'networkidle' });
  await page.getByLabel('Title').fill('Will Fail Review');
  await page.getByLabel('Target Type').click();
  await page.getByRole('option', { name: 'Work Permit', exact: true }).click();
  await page.getByLabel('Target ID').fill('2');

  await page.getByRole('button', { name: 'Create Review Request' }).click();
  await page.waitForTimeout(2000);
  await page.screenshot({ path: `${__dirname}/repro-fail-01.png` });

  const createBtn = page.getByRole('button', { name: 'Create Review Request' });
  const cancelBtn = page.getByRole('button', { name: 'Cancel' });
  console.log('Create button disabled:', await createBtn.isDisabled());
  console.log('Cancel button disabled:', await cancelBtn.isDisabled());
  console.log('Current URL (should still be /reviews/new if stuck):', page.url());

  await browser.close();
})();

