const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('pageerror', (err) => console.log('[pageerror]', err.message));

  console.log('--- Create form: should have NO Review Status section ---');
  await page.goto('http://localhost:5173/reviews/new', { waitUntil: 'networkidle' });
  await page.waitForSelector('text=New Review Request');
  const statusSectionOnCreate = await page.locator('text=Review Status').count();
  console.log('Review Status section present on create form:', statusSectionOnCreate > 0);

  console.log('--- Create form: Target field should be a Work Permit dropdown with real names ---');
  await page.waitForSelector('text=Work Permit');
  await page.getByLabel('Work Permit').click();
  await page.screenshot({ path: `${__dirname}/ux-01-permit-dropdown-open.png` });
  const options = await page.getByRole('option').allTextContents();
  console.log('Permit dropdown options:', options);
  await page.getByRole('option', { name: /Employment Pass \(Employment Pass\)/ }).click();

  await page.getByLabel('Title').fill('UX Fix Verification Review');
  await page.screenshot({ path: `${__dirname}/ux-02-create-filled.png` });

  await page.getByRole('button', { name: 'Create Review Request' }).click();
  await page.waitForURL(/\/reviews\/\d+$/);
  console.log('Created, now at:', page.url());
  await page.screenshot({ path: `${__dirname}/ux-03-detail-after-create.png` });

  console.log('--- Edit form: SHOULD have Review Status section, and permit pre-selected ---');
  await page.getByRole('button', { name: 'Edit' }).click();
  await page.waitForSelector('text=Edit Review Request');
  const statusSectionOnEdit = await page.locator('text=Review Status').count();
  console.log('Review Status section present on edit form:', statusSectionOnEdit > 0);
  const selectedPermitText = await page.getByLabel('Work Permit').innerText();
  console.log('Pre-selected permit shown on edit:', selectedPermitText);
  await page.screenshot({ path: `${__dirname}/ux-04-edit-form.png` });

  console.log('--- Compliance Record target type: should fall back to manual ID field ---');
  await page.getByLabel('Target Type').click();
  await page.getByRole('option', { name: 'Compliance Record' }).click();
  await page.waitForSelector('text=Compliance Record ID');
  await page.screenshot({ path: `${__dirname}/ux-05-compliance-record-fallback.png` });

  await browser.close();
})();

